struct Recording { let id: Int; let title: String }
protocol RecordingDelegate: AnyObject {
    func recordingFinished(_ value: Recording)
}
final class Recorder {
    weak var delegate: (any RecordingDelegate)?
    func finish(_ value: Recording) { delegate?.recordingFinished(value) }
}
final class RecordLog: RecordingDelegate {
    var ids: [Int] = []
    func recordingFinished(_ value: Recording) { ids.append(value.id) }
}
let recorder = Recorder()
var log: RecordLog? = RecordLog()
recorder.delegate = log
recorder.finish(Recording(id: 21, title: "Прогулка"))
print(log?.ids ?? [])
log = nil
print(recorder.delegate == nil)
recorder.finish(Recording(id: 22, title: "Идея"))

