import Foundation
extension Notification.Name {
    static let recordingSaved = Notification.Name("recordingSaved")
}
final class LibraryBadge {
    let center: NotificationCenter
    private var token: NSObjectProtocol?
    private(set) var ids: [Int] = []
    init(center: NotificationCenter) { self.center = center }
    func start() {
        stop()
        token = center.addObserver(
            forName: .recordingSaved, object: nil, queue: nil
        ) { [weak self] note in
            guard let id = note.userInfo?["id"] as? Int else { return }
            self?.ids.append(id)
        }
    }
    func stop() {
        if let token { center.removeObserver(token) }
        token = nil
    }
    deinit { stop() }
}
let center = NotificationCenter()
let badge = LibraryBadge(center: center)
badge.start()
center.post(name: .recordingSaved, object: nil, userInfo: ["id": 21])
badge.stop()
center.post(name: .recordingSaved, object: nil, userInfo: ["id": 22])
assert(badge.ids == [21])

