struct Recording { let id: Int; let title: String }
protocol RecordingPreview { func label(_ value: Recording) -> String }
struct CompactPreview: RecordingPreview {
    func label(_ value: Recording) -> String { value.title }
}
struct DetailPreview: RecordingPreview {
    func label(_ value: Recording) -> String { "\(value.id): \(value.title)" }
}
class PreviewCreator {
    func makePreview() -> any RecordingPreview { CompactPreview() }
    func preview(_ value: Recording) -> String { makePreview().label(value) }
}
final class DetailCreator: PreviewCreator {
    override func makePreview() -> any RecordingPreview { DetailPreview() }
}
let creator: PreviewCreator = DetailCreator()
assert(creator.preview(Recording(id: 21, title: "Прогулка")) == "21: Прогулка")

